import base64
import json
import re


def as_data(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return value
    return value


def as_list(value, *keys):
    value = as_data(value)
    if isinstance(value, list):
        return value
    if isinstance(value, dict):
        for key in keys:
            if isinstance(value.get(key), list):
                return value[key]
    return []


def norm(text):
    text = str(text or "").lower()
    text = re.sub(r"\b(pty|ltd|limited|the|trust)\b", " ", text)
    return re.sub(r"[^a-z0-9]+", " ", text).strip()


def field(row, key):
    data = row.get("data") or row.get("fields") or {}
    return data.get(key, row.get(key))


pending = []
cursor = None
for _ in range(25):
    page = api.records.list(type_slug="ap_bill", limit=200, cursor=cursor) if cursor else api.records.list(type_slug="ap_bill", limit=200)
    for row in page.get("records") or page.get("items") or []:
        if field(row, "pdf_attached") is True:
            continue
        if field(row, "document_artifact_id") and field(row, "xero_tenant_id") and field(row, "invoice_number"):
            pending.append(row)
    cursor = page.get("nextCursor") or page.get("next_cursor")
    if not cursor:
        break

attached = 0
waiting = 0
issues = []
for row in pending[:100]:
    tenant = field(row, "xero_tenant_id")
    number = str(field(row, "invoice_number"))
    supplier = norm(field(row, "supplier_name"))
    try:
        found = as_list(api.connectors.invoke(server="xero-accounting", tool="list_invoices", args={"xero_tenant_id": tenant, "invoiceNumbers": [number], "where": "Type==\"ACCPAY\""}), "Invoices", "invoices")
        live = [b for b in found if b.get("Status") not in ("DELETED", "VOIDED")]
        same = [b for b in live if not supplier or norm((b.get("Contact") or {}).get("Name")) in (supplier,) or supplier in norm((b.get("Contact") or {}).get("Name")) or norm((b.get("Contact") or {}).get("Name")) in supplier]
        if len(same) != 1:
            waiting += 1
            continue
        bill = same[0]
        path = api.artifacts.get(artifact_id=field(row, "document_artifact_id"))
        if not isinstance(path, str):
            issues.append(f"{number}: the stored PDF couldn't be read")
            continue
        with open(path, "rb") as fh:
            content = base64.b64encode(fh.read()).decode("ascii")
        name = str(field(row, "attachment_name") or f"{number}.pdf")
        mime = "application/pdf" if name.lower().endswith(".pdf") else "image/jpeg"
        api.connectors.invoke(server="xero-accounting", tool="upload_attachment", args={"xero_tenant_id": tenant, "hostType": "Invoices", "hostId": bill.get("InvoiceID"), "fileName": name, "base64Content": content, "mimeType": mime, "includeOnline": False})
        api.records.update(type_slug="ap_bill", record_id=row.get("id"), record={"pdf_attached": True, "xero_bill_id": bill.get("InvoiceID")})
        attached += 1
    except Exception as err:
        issues.append(f"{number}: {err}")

problems = "\n".join(issues)
